# SecretRotation.ps1
#
# Library of pure functions for the Secret Rotation Validator.
#
# IMPORTANT: this file only *defines* functions. Dot-sourcing it has no side
# effects (no code runs at import time), so both the Pester suite and the CLI
# entry point (Validate-SecretRotation.ps1) can safely load it.
#
# The whole logic layer is kept free of I/O-at-load and free of "what is today":
# callers pass an explicit -AsOf date so behaviour is fully deterministic and
# unit-testable.

Set-StrictMode -Version Latest

# Canonical date format for all dates in configs and output.
$script:DateFormat = 'yyyy-MM-dd'

function ConvertTo-RotationDate {
    <#
    .SYNOPSIS
        Parse an ISO yyyy-MM-dd string into a [datetime], or throw clearly.
    #>
    param([Parameter(Mandatory)][string]$Value)

    $parsed = [datetime]::MinValue
    $ok = [datetime]::TryParseExact(
        $Value, $script:DateFormat,
        [System.Globalization.CultureInfo]::InvariantCulture,
        [System.Globalization.DateTimeStyles]::None, [ref]$parsed)
    if (-not $ok) {
        throw "invalid date '$Value' (expected $script:DateFormat)"
    }
    return $parsed.Date
}

function Read-SecretConfig {
    <#
    .SYNOPSIS
        Load and validate a secrets config JSON file into secret objects.
    .DESCRIPTION
        Accepts a file shaped as { "secrets": [ { name, lastRotated,
        rotationPolicyDays, requiredBy }, ... ] }. Every failure mode throws an
        actionable message naming the file / field at fault.
    #>
    param([Parameter(Mandatory)][string]$Path)

    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) {
        throw "Config file not found: $Path"
    }

    $raw = Get-Content -LiteralPath $Path -Raw
    try {
        $data = $raw | ConvertFrom-Json -ErrorAction Stop
    } catch {
        throw "Config file is not valid JSON: $Path ($($_.Exception.Message))"
    }

    if ($null -eq $data.PSObject.Properties['secrets'] -or $null -eq $data.secrets) {
        throw "Config file is missing a top-level 'secrets' array: $Path"
    }
    $secrets = @($data.secrets)

    # Required fields are validated in a fixed order so the error a user sees is
    # stable and points at the first real problem.
    $required = @('name', 'lastRotated', 'rotationPolicyDays', 'requiredBy')
    foreach ($s in $secrets) {
        foreach ($field in $required) {
            $prop = $s.PSObject.Properties[$field]
            if ($null -eq $prop -or $null -eq $prop.Value) {
                $name = if ($s.PSObject.Properties['name']) { $s.name } else { '<unnamed>' }
                throw "Secret '$name' is missing required field '$field'"
            }
        }

        # lastRotated must be a real ISO date.
        $parsed = [datetime]::MinValue
        $dateOk = [datetime]::TryParseExact(
            [string]$s.lastRotated, $script:DateFormat,
            [System.Globalization.CultureInfo]::InvariantCulture,
            [System.Globalization.DateTimeStyles]::None, [ref]$parsed)
        if (-not $dateOk) {
            throw ("Secret '$($s.name)' has an invalid lastRotated date: " +
                   "'$($s.lastRotated)' (expected $script:DateFormat)")
        }

        # rotationPolicyDays must be a positive integer.
        $policy = 0
        if (-not [int]::TryParse([string]$s.rotationPolicyDays, [ref]$policy) -or $policy -le 0) {
            throw ("Secret '$($s.name)' rotationPolicyDays must be a positive " +
                   "integer (got '$($s.rotationPolicyDays)')")
        }
    }

    return $secrets
}

function Get-RotationStatus {
    <#
    .SYNOPSIS
        Classify a single secret relative to -AsOf.
    .OUTPUTS
        A pscustomobject with: name, lastRotated, rotationPolicyDays,
        requiredBy, dueDate (yyyy-MM-dd), daysUntilDue (int, negative = overdue),
        status (expired | warning | ok).
    .NOTES
        Warning window is inclusive on both edges:
            daysUntilDue < 0                       -> expired
            0 <= daysUntilDue <= WarningWindowDays -> warning
            daysUntilDue > WarningWindowDays       -> ok
    #>
    param(
        [Parameter(Mandatory)]$Secret,
        [Parameter(Mandatory)][datetime]$AsOf,
        [int]$WarningWindowDays = 14
    )

    $lastRotated = ConvertTo-RotationDate ([string]$Secret.lastRotated)
    $policy = [int]$Secret.rotationPolicyDays
    $due = $lastRotated.AddDays($policy)
    $daysUntilDue = [int][math]::Round((($due.Date) - ($AsOf.Date)).TotalDays)

    $status =
        if ($daysUntilDue -lt 0) { 'expired' }
        elseif ($daysUntilDue -le $WarningWindowDays) { 'warning' }
        else { 'ok' }

    [pscustomobject]@{
        name              = $Secret.name
        lastRotated       = [string]$Secret.lastRotated
        rotationPolicyDays = $policy
        requiredBy        = @($Secret.requiredBy)
        dueDate           = $due.ToString($script:DateFormat)
        daysUntilDue      = $daysUntilDue
        status            = $status
    }
}

function New-RotationReport {
    <#
    .SYNOPSIS
        Evaluate every secret and group the results by urgency.
    .OUTPUTS
        A pscustomobject with generatedAt, warningWindowDays, groups
        (expired/warning/ok arrays, most-urgent-first), and a summary.
    #>
    param(
        [Parameter(Mandatory)]$Secrets,
        [Parameter(Mandatory)][datetime]$AsOf,
        [int]$WarningWindowDays = 14
    )

    $evaluated = @(
        foreach ($s in @($Secrets)) {
            Get-RotationStatus -Secret $s -AsOf $AsOf -WarningWindowDays $WarningWindowDays
        }
    )

    # Sort each bucket by daysUntilDue ascending = most urgent first.
    $expired = @($evaluated | Where-Object { $_.status -eq 'expired' } | Sort-Object daysUntilDue)
    $warning = @($evaluated | Where-Object { $_.status -eq 'warning' } | Sort-Object daysUntilDue)
    $ok      = @($evaluated | Where-Object { $_.status -eq 'ok' }      | Sort-Object daysUntilDue)

    [pscustomobject]@{
        generatedAt       = $AsOf.ToString($script:DateFormat)
        warningWindowDays = $WarningWindowDays
        groups = [pscustomobject]@{
            expired = $expired
            warning = $warning
            ok      = $ok
        }
        summary = [pscustomobject]@{
            total   = $evaluated.Count
            expired = $expired.Count
            warning = $warning.Count
            ok      = $ok.Count
        }
    }
}

function Format-RotationReportJson {
    <#
    .SYNOPSIS
        Render the report as JSON.
    #>
    param([Parameter(Mandatory)]$Report)
    return ($Report | ConvertTo-Json -Depth 10)
}

function Format-RotationReportMarkdown {
    <#
    .SYNOPSIS
        Render the report as a Markdown document with one table per urgency.
    #>
    param([Parameter(Mandatory)]$Report)

    $statusLabel = @{ expired = 'EXPIRED'; warning = 'WARNING'; ok = 'OK' }
    $lines = [System.Collections.Generic.List[string]]::new()

    $lines.Add('# Secret Rotation Report')
    $lines.Add('')
    $s = $Report.summary
    $lines.Add("**Summary:** $($s.expired) expired, $($s.warning) warning, " +
               "$($s.ok) ok (of $($s.total) secrets, as of $($Report.generatedAt), " +
               "warning window $($Report.warningWindowDays) days)")
    $lines.Add('')

    foreach ($key in @('expired', 'warning', 'ok')) {
        $rows = @($Report.groups.$key)
        $lines.Add("## $($statusLabel[$key]) ($($rows.Count))")
        $lines.Add('')
        if ($rows.Count -eq 0) {
            $lines.Add('_None._')
            $lines.Add('')
            continue
        }
        $lines.Add('| Secret | Status | Last Rotated | Due Date | Days Until Due | Required By |')
        $lines.Add('| --- | --- | --- | --- | --- | --- |')
        foreach ($r in $rows) {
            $svc = (@($r.requiredBy) -join ', ')
            if ([string]::IsNullOrEmpty($svc)) { $svc = '-' }
            $lines.Add("| $($r.name) | $($statusLabel[$key]) | $($r.lastRotated) | " +
                       "$($r.dueDate) | $($r.daysUntilDue) | $svc |")
        }
        $lines.Add('')
    }

    return (($lines -join "`n").TrimEnd() + "`n")
}

function Invoke-SecretRotationValidator {
    <#
    .SYNOPSIS
        End-to-end: load config, build report, render in the requested format.
    #>
    param(
        [Parameter(Mandatory)][string]$Path,
        [datetime]$AsOf = [datetime]::Today,
        [int]$WarningWindowDays = 14,
        [string]$Format = 'markdown'
    )

    $fmt = $Format.ToLowerInvariant()
    if ($fmt -notin @('markdown', 'json')) {
        throw "Unsupported format: '$Format' (expected 'markdown' or 'json')"
    }

    $secrets = Read-SecretConfig -Path $Path
    $report  = New-RotationReport -Secrets $secrets -AsOf $AsOf -WarningWindowDays $WarningWindowDays

    switch ($fmt) {
        'markdown' { return Format-RotationReportMarkdown -Report $report }
        'json'     { return Format-RotationReportJson -Report $report }
    }
}

